const POS = { n: 'noun', v: 'verb', adj: 'adj', adv: 'adv', idiom: 'idiom' };
const split = s => (s ? s.split('|') : []);

// Round-robin across topics so a day's new cards cover several themes.
const entries = [];
const lists = Object.entries(T);
const max = Math.max(...lists.map(([, l]) => l.length));
for (let i = 0; i < max; i++) {
  lists.forEach(([topic, list], ti) => {
    const w = list[i];
    if (!w) return;
    const [term, pos, tr, defEn, ex, cloze, colloc, syn, family, note] = w;
    entries.push({
      term, src: 'topics', order: i * 100 + ti, pos: POS[pos] || pos, cefr: 'C1',
      data: {
        type: 'word', pos: POS[pos] || pos, tr, defEn, topic, cefr: 'C1',
        examples: [ex], cloze: [cloze], collocations: split(colloc), synonyms: split(syn), family, note,
        dictFetched: /\s/.test(term), // single words still get IPA + recorded audio from the dictionary
      },
    });
  });
}
export const TOPIC_WORDS = entries;
